  `branch_address_en` varchar(255) NOT NULL,
  `branch_address_si` varchar(255) NOT NULL,
  `branch_address_ta` varchar(255) NOT NULL,
  `region_name_en` varchar(100) NOT NULL,
  `region_name_si` varchar(100) NOT NULL,
  `region_name_ta` varchar(100) NOT NULL,
  `contact_number` varchar(10) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `coordinates_longitude` varchar(100) NOT NULL,
  `coordinates_latitude` varchar(100) NOT NULL,
  `last_updated_by` varchar(100) DEFAULT 'Backend',
  `last_updated_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=107 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
